import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at register time when the inputSchema is uncompilable and the message names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('compiles a static tool inputSchema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      get inputSchema(): Record<string, unknown> {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async () => 'sunny');

    for (let i = 0; i < 10; i += 1) {
      await registry.execute('get_weather', {location: 'Amsterdam'});
    }

    expect(schemaReads).toBe(1);
  });
});

