    };
    const schemaB: Record<string, unknown> = {
      type: 'object',
      properties: {postalCode: {type: 'string'}},
      required: ['postalCode'],
    };
    let activeSchema = schemaA;
    const executedInputs: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Switches schema between calls',
        inputSchema: activeSchema,
      }),
      async input => {
        executedInputs.push(input);
        return 'ok';
      }
    );

    const firstCall = await registry.execute('dynamic_lookup', {city: 'Berlin'});
    const cachedRepeatCall = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const readsAfterTwoSchemaACalls = typeReadsSchemaA;

    activeSchema = schemaB;
    const staleInputRejected = await registry.execute('dynamic_lookup', {city: 'Berlin'});
    const updatedInputAccepted = await registry.execute('dynamic_lookup', {postalCode: '10115'});

    expect({
      firstCall: firstCall.result,
      cachedRepeatCall: cachedRepeatCall.result,
      readsAfterTwoSchemaACalls,
      staleInputMentionsPostalCode:
        staleInputRejected.result.includes('postalCode') && /required/i.test(staleInputRejected.result),
      updatedInputAccepted: updatedInputAccepted.result,
      executedInputs,
    }).toEqual({
