export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({allErrors: true, format: false});
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, Ajv.ValidateFunction>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema before calling its executor (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.getValidator(name, tool);
    if (!validate(input)) {
      const errors = this.describeValidationErrors(validate.errors ?? []);
      log.warn('tool', 'input validation failed', {name, errors});
      return {result: `Invalid input for tool "${name}": ${errors.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getValidator(toolName: string, tool: StoredTool): Ajv.ValidateFunction {
    if (tool.validator) {
      return tool.validator;
    }
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) {
      return cached;
    }
    const compiled = this.compileSchema(toolName, schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(toolName: string, schema: ToolDefinition['inputSchema']): Ajv.ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`);
    }
  }

  private describeValidationErrors(errors: Ajv.ErrorObject[]): string[] {
    return errors.map(err => this.describeValidationError(err));
  }

  private describeValidationError(err: Ajv.ErrorObject): string {
    const path = err.dataPath ? err.dataPath.replace(/^\./, '') : 'input';
    if (err.keyword === 'required') {
      const missingProperty = (err.params as Ajv.RequiredParams).missingProperty;
      const fullPath = err.dataPath ? `${path}.${missingProperty}` : missingProperty;
      return `missing required property "${fullPath}"`;
    }
    if (err.keyword === 'type') {
      const expectedType = (err.params as Ajv.TypeParams).type;
      return `"${path}" must be of type ${expectedType}`;
    }
    if (err.keyword === 'enum') {
      const allowedValues = (err.params as Ajv.EnumParams).allowedValues.map(String).join(', ');
      return `"${path}" must be one of [${allowedValues}]`;
    }
    return `"${path}" ${err.message ?? `failed "${err.keyword}" validation`}`;
  }
}

